#!/bin/bash
#SBATCH --account=def-khenni
#SBATCH --job-name=bottleneck_comparison-s0
#SBATCH --time=60:00:00
#SBATCH --cpus-per-task=32
#SBATCH --mem=64G
#SBATCH --output=logs/%x-%j.out
#SBATCH --error=logs/%x-%j.err
#SBATCH --requeue

# Generated by scripts/narval/submit.py. Edit the study config, not this file.

# Repair CRLF endings if the file was touched on Windows.
if grep -q $'\r' "$0" 2>/dev/null; then
  sed -i 's/\r$//' "$0"
  exec bash "$0" "$@"
fi

source "${SLURM_SUBMIT_DIR:-$HOME/eeg_qgan}/scripts/narval/_common.sh"

echo "study bottleneck_comparison"
echo "args  --seed-index 0"

python -m eeg_qgan.experiments.runner bottleneck_comparison \
  --data-root "$DATA_ROOT" \
  --output-root "$OUTPUT_ROOT" \
  --seed-index 0

echo "finished $(date --iso-8601=seconds)"
